def min_covering_window(values, required):
    if not required:
        return [0, 0]
    need = {}
    for x in required:
        need[x] = need.get(x, 0) + 1
    missing = len(required)
    have = {}
    left = 0
    best_len = float('inf')
    best_start = -1
    for right, val in enumerate(values):
        if val in need:
            have[val] = have.get(val, 0) + 1
            if have[val] <= need[val]:
                missing -= 1
        while missing == 0:
            cur_len = right - left + 1
            if cur_len < best_len:
                best_len = cur_len
                best_start = left
            left_val = values[left]
            if left_val in need:
                if have[left_val] <= need[left_val]:
                    missing += 1
                have[left_val] -= 1
            left += 1
    if best_start == -1:
        return None
    return [best_start, best_start + best_len]

